    short shIntervalInside;
    undefined field7_0x26;
    undefined field8_0x27;
    undefined field9_0x28;
    undefined field10_0x29;
    struct kgtCharacterCPUCommandSkillFull kgtCharacterCPUCommandSkill_1;
